#include <ctype.h>
#include <stdio.h>
#include <string.h>

static const char *const c11_keywords[] = {
    "_Alignas", "_Alignof", "_Atomic", "_Bool", "_Complex",
    "_Generic", "_Imaginary", "_Noreturn", "_Static_assert",
    "_Thread_local", "auto", "break", "case", "char", "const",
    "continue", "default", "do", "double", "else", "enum",
    "extern", "float", "for", "goto", "if", "inline", "int",
    "long", "register", "restrict", "return", "short", "signed",
    "sizeof", "static", "struct", "switch", "typedef", "union",
    "unsigned", "void", "volatile", "while"
};

static int is_keyword(const char *word)
{
    size_t i;
    const size_t count = sizeof c11_keywords / sizeof c11_keywords[0];

    for (i = 0U; i < count; ++i) {
        if (strcmp(word, c11_keywords[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

/* This helper checks the basic ASCII identifier form used in this example. */
static int is_basic_identifier(const char *text)
{
    const unsigned char *p = (const unsigned char *)text;

    if (*p == '\0' || !(isalpha(*p) || *p == '_')) {
        return 0;
    }
    ++p;
    while (*p != '\0') {
        if (!(isalnum(*p) || *p == '_')) {
            return 0;
        }
        ++p;
    }
    return 1;
}

int main(void)
{
    const char *const samples[] = {
        "while", "student_count", "_temporary", "9lives", "total-cost"
    };
    size_t i;
    const size_t count = sizeof samples / sizeof samples[0];

    for (i = 0U; i < count; ++i) {
        const char *word = samples[i];

        if (!is_basic_identifier(word)) {
            printf("%-16s invalid basic identifier form\n", word);
        } else if (is_keyword(word)) {
            printf("%-16s C11 keyword\n", word);
        } else {
            printf("%-16s identifier\n", word);
        }
    }

    puts("\nExample tokens in: int total = 3 + 4;");
    puts("int       keyword");
    puts("total     identifier");
    puts("= + ;     punctuators");
    puts("3 and 4   integer constants");
    return 0;
}

